style.css:
/* =========================================================
   DISCORD AUTOHIDE - INSTANT REVEAL, BLACKOUT IMAGES, 3S DELAY
   ========================================================= */

/* --- 1. MESSAGE TEXT --- */
[class*="messageContent"] {
    filter: blur(7px) contrast(80%) !important;
    opacity: 0.5 !important;
    user-select: none !important;
    /* Delay re-blur for 3s after mouse leaves */
    transition: filter 0.4s ease 3s, opacity 0.4s ease 3s !important;
}

[class*="messageContent"]:hover {
    filter: blur(0) contrast(100%) !important;
    opacity: 1 !important;
    user-select: text !important;
    /* Fixed: Instant unblur on hover */
    transition: filter 0s, opacity 0s !important;
}

/* --- 2. IMAGES, GIFS, VIDEOS, EMBEDS & STICKERS (BLACKOUT) --- */
[class*="mediaAttachments"],
[class*="imageWrapper"],
[class*="embedFull"],
[class*="embedMedia"],
[class*="oneByOneGrid"],
[class*="accessory"] img,
[class*="accessory"] video,
[class*="stickerContainer"] {
    /* Brightness 0 turns the media entirely black */
    filter: brightness(0) !important; 
    opacity: 1 !important;
    /* Delay going back to black for 3s after mouse leaves */
    transition: filter 0.4s ease 3s !important;
}

[class*="mediaAttachments"]:hover,
[class*="imageWrapper"]:hover,
[class*="embedFull"]:hover,
[class*="embedMedia"]:hover,
[class*="oneByOneGrid"]:hover,
[class*="accessory"] img:hover,
[class*="accessory"] video:hover,
[class*="stickerContainer"]:hover {
    /* Restores normal colors */
    filter: brightness(1) !important; 
    opacity: 1 !important;
    /* Instant reveal on hover */
    transition: filter 0s !important; 
}
